insert into wp_questions (bank_grade, skill, position, type, payload) select 4, 'because-when', 1, 'pick_one', '{"prompt":"One of these is right. Tap it.","choices":["Because the bus was late. We missed the show.","Because the bus was late we missed the show.","Because the bus was late, we missed the show.","Because, the bus was late we missed the show."],"answer":2}'::jsonb
